<template><div><div v-for="(item,i) in items" :key="i" style="margin:8px 0"><div style="display:flex;justify-content:space-between;font-size:13px"><span>{{item.label}}</span><strong>{{item.display ?? item.value}}</strong></div><div class="progress"><i :style="{width: pct(item.value)+'%', background: item.color || 'var(--azul)'}"></i></div></div><p v-if="!items.length" style="color:var(--gris)">Sin datos todavía.</p></div></template>
<script setup>import {computed} from 'vue'; const props=defineProps({items:{type:Array,default:()=>[]}}); const max=computed(()=>Math.max(1,...props.items.map(x=>x.value||0))); const pct=v=>Math.round((v||0)/max.value*100)</script>
